-- LEP: titulo nas linhas filhas (incisos, paragrafos, alineas) dos 11 artigos com letra, que haviam ficado com titulo nulo (15/10/2026).
-- Revert: update legislacao set titulo=null where codigo='lep' and titulo is not null and (inciso is not null or paragrafo is not null);
update legislacao l set titulo=v.t from (values
(9,null::text,$$1$$,$$§ 1º A identificação do perfil genético será armazenada em banco de dados sigiloso, conforme regulamento a ser expedido pelo Poder Executivo. (Incluído pela Lei nº 12.654, de 2012)$$,$$Art. 9-A$$),
(9,null::text,$$1-A$$,$$§ 1º-A. A regulamentação deverá fazer constar garantias mínimas de proteção de dados genéticos, observando as melhores práticas da genética forense. (Incluído pela Lei nº 13.964, de 2019) (Vigência)$$,$$Art. 9-A$$),
(9,null::text,$$2$$,$$§ 2º A autoridade policial, federal ou estadual, poderá requerer ao juiz competente, no caso de inquérito instaurado, o acesso ao banco de dados de identificação de perfil genético. (Incluído pela Lei nº 12.654, de 2012)$$,$$Art. 9-A$$),
(9,null::text,$$3$$,$$§ 3º Deve ser viabilizado ao titular de dados genéticos o acesso aos seus dados constantes nos bancos de perfis genéticos, bem como a todos os documentos da cadeia de custódia que gerou esse dado, de maneira que possa ser contraditado pela defesa. (Incluído pela Lei nº 13.964, de 2019) (Vigência)$$,$$Art. 9-A$$),
(9,null::text,$$4$$,$$§ 4º O condenado pelos crimes previstos no caput deste artigo que não tiver sido submetido à identificação do perfil genético por ocasião do ingresso no estabelecimento prisional deverá ser submetido ao procedimento durante o cumprimento da pena. (Incluído pela Lei nº 13.964, de 2019) (Vigência)$$,$$Art. 9-A$$),
(9,null::text,$$5$$,$$§ 5º A amostra biológica coletada só poderá ser utilizada para o único e exclusivo fim de permitir a identificação pelo perfil genético, não estando autorizadas as práticas de fenotipagem genética. (Redação dada pela Lei nº 15.295, de 2025) Vigência$$,$$Art. 9-A$$),
(9,null::text,$$6$$,$$§ 6º Uma vez identificado o perfil genético, a amostra biológica recolhida nos termos do caput deste artigo deverá ser correta e imediatamente descartada, guardando-se material suficiente para a eventualidade de nova perícia, nos termos do regulamento, vedada a sua utilização para qualquer outro fim. (Redação dada pela Lei nº 15.295, de 2025) Vigência$$,$$Art. 9-A$$),
(9,null::text,$$7$$,$$§ 7º A coleta da amostra biológica será realizada por agente público treinado e respeitará os procedimentos de cadeia de custódia definidos pela legislação em vigor e complementados pelo órgão de perícia oficial de natureza criminal. (Redação dada pela Lei nº 15.295, de 2025) Vigência$$,$$Art. 9-A$$),
(9,null::text,$$8$$,$$§ 8º Constitui falta grave a recusa do condenado em submeter-se ao procedimento de identificação do perfil genético. (Incluído pela Lei nº 13.964, de 2019) (Vigência)$$,$$Art. 9-A$$),
(9,null::text,$$9$$,$$§ 9º A elaboração do laudo da amostra biológica coletada nos termos do § 7º será realizada por perito oficial. (Incluído pela Lei nº 15.295, de 2025) Vigência$$,$$Art. 9-A$$),
(9,null::text,$$10$$,$$§ 10. Nos casos dos crimes hediondos e equiparados, o processamento dos vestígios biológicos coletados em locais de crime e corpos de delito e a inclusão dos respectivos perfis genéticos no banco deverão ser realizados, se possível, em até 30 (trinta) dias contados da recepção da amostra pelo laboratório de DNA. (Incluído pela Lei nº 15.295, de 2025) Vigência$$,$$Art. 9-A$$),
(18,null::text,$$1$$,$$§ 1º O ensino ministrado aos presos e presas integrar-se-á ao sistema estadual e municipal de ensino e será mantido, administrativa e financeiramente, com o apoio da União, não só com os recursos destinados à educação, mas pelo sistema estadual de justiça ou administração penitenciária. (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 18-A$$),
(18,null::text,$$2$$,$$§ 2º Os sistemas de ensino oferecerão aos presos e às presas cursos supletivos de educação de jovens e adultos. (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 18-A$$),
(18,null::text,$$3$$,$$§ 3º A União, os Estados, os Municípios e o Distrito Federal incluirão em seus programas de educação à distância e de utilização de novas tecnologias de ensino, o atendimento aos presos e às presas. 7.627 (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 18-A$$),
(21,$$I$$,null::text,$$I - o nível de escolaridade dos presos e das presas; (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 21-A$$),
(21,$$II$$,null::text,$$II - a existência de cursos nos níveis fundamental e médio e o número de presos e presas atendidos; (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 21-A$$),
(21,$$III$$,null::text,$$III - a implementação de cursos profissionais em nível de iniciação ou aperfeiçoamento técnico e o número de presos e presas atendidos; (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 21-A$$),
(21,$$IV$$,null::text,$$IV - a existência de bibliotecas e as condições de seu acervo; (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 21-A$$),
(21,$$V$$,null::text,$$V - outros dados relevantes para o aprimoramento educacional de presos e presas. (Incluído pela Lei nº 13.163, de 2015)$$,$$Art. 21-A$$),
(41,null::text,$$1$$,$$§ 1º O monitoramento poderá ser requerido pelo delegado de polícia, pelo Ministério Público ou pela administração penitenciária. (Incluído pela Lei nº 15.358, de 2026)$$,$$Art. 41-A$$),
(41,null::text,$$2$$,$$§ 2º A visitação e o monitoramento nos estabelecimentos penais federais de segurança máxima ficam sujeitos às regras especiais previstas na Lei nº 11.671, de 8 de maio de 2008. (Incluído pela Lei nº 15.358, de 2026)$$,$$Art. 41-A$$),
(41,null::text,$$1$$,$$§ 1º O juízo de controle decidirá sobre a licitude, a pertinência e a necessidade da prova e sobre a sua eventual inutilização, antes de qualquer remessa ao juízo da instrução. (Incluído pela Lei nº 15.358, de 2026)$$,$$Art. 41-B$$),
(41,null::text,$$2$$,$$§ 2º As gravações ou os registros que não interessarem à prova deverão ser inutilizados por decisão fundamentada do juízo de controle, a requerimento do Ministério Público ou da parte interessada, facultada a presença do acusado ou de seu defensor. (Incluído pela Lei nº 15.358, de 2026)$$,$$Art. 41-B$$),
(41,null::text,$$3$$,$$§ 3º O conteúdo das comunicações indeferidas ou declaradas ilícitas não poderá ser acessado, direta ou indiretamente, pelo juízo da instrução criminal. (Incluído pela Lei nº 15.358, de 2026)$$,$$Art. 41-B$$),
(81,$$I$$,null::text,$$I - requerer: (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$)
) as v(n,i,p,x,t) where l.codigo='lep' and l.numero=v.n and l.titulo is null and l.inciso is not distinct from v.i and l.paragrafo is not distinct from v.p and l.texto=v.x;
update legislacao l set titulo=v.t from (values
(81,$$I-a$$,null::text,$$a) todas as providências necessárias ao desenvolvimento do processo executivo; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-b$$,null::text,$$b) a aplicação aos casos julgados de lei posterior que de qualquer modo favorecer o condenado; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-c$$,null::text,$$c) a declaração de extinção da punibilidade; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-d$$,null::text,$$d) a unificação de penas; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-e$$,null::text,$$e) a detração e remição da pena; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-f$$,null::text,$$f) a instauração dos incidentes de excesso ou desvio de execução; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-g$$,null::text,$$g) a aplicação de medida de segurança e sua revogação, bem como a substituição da pena por medida de segurança; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-h$$,null::text,$$h) a conversão de penas, a progressão nos regimes, a suspensão condicional da pena, o livramento condicional, a comutação de pena e o indulto; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-i$$,null::text,$$i) a autorização de saídas temporárias; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-j$$,null::text,$$j) a internação, a desinternação e o restabelecimento da situação anterior; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-k$$,null::text,$$k) o cumprimento de pena ou medida de segurança em outra comarca; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$I-l$$,null::text,$$l) a remoção do condenado na hipótese prevista no § 1º do art. 86 desta Lei; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$II$$,null::text,$$II - requerer a emissão anual do atestado de pena a cumprir; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$III$$,null::text,$$III - interpor recursos de decisões proferidas pela autoridade judiciária ou administrativa durante a execução; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$IV$$,null::text,$$IV - representar ao Juiz da execução ou à autoridade administrativa para instauração de sindicância ou procedimento administrativo em caso de violação das normas referentes à execução penal; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$V$$,null::text,$$V - visitar os estabelecimentos penais, tomando providências para o adequado funcionamento, e requerer, quando for o caso, a apuração de responsabilidade; (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,$$VI$$,null::text,$$VI - requerer à autoridade competente a interdição, no todo ou em parte, de estabelecimento penal. (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(81,null::text,$$único$$,$$Parágrafo único. O órgão da Defensoria Pública visitará periodicamente os estabelecimentos penais, registrando a sua presença em livro próprio. (Incluído pela Lei nº 12.313, de 2010).$$,$$Art. 81-B$$),
(83,$$I$$,null::text,$$I - serviços de conservação, limpeza, informática, copeiragem, portaria, recepção, reprografia, telecomunicações, lavanderia e manutenção de prédios, instalações e equipamentos internos e externos; (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-A$$),
(83,$$II$$,null::text,$$II - serviços relacionados à execução de trabalho pelo preso. (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-A$$),
(83,null::text,$$1$$,$$§ 1º A execução indireta será realizada sob supervisão e fiscalização do poder público. (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-A$$),
(83,null::text,$$2$$,$$§ 2º Os serviços relacionados neste artigo poderão compreender o fornecimento de materiais, equipamentos, máquinas e profissionais. (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-A$$),
(83,$$I$$,null::text,$$I - classificação de condenados; (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-B$$),
(83,$$II$$,null::text,$$II - aplicação de sanções disciplinares; (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-B$$),
(83,$$III$$,null::text,$$III - controle de rebeliões; (Incluído pela Lei nº 13.190, de 2015).$$,$$Art. 83-B$$)
) as v(n,i,p,x,t) where l.codigo='lep' and l.numero=v.n and l.titulo is null and l.inciso is not distinct from v.i and l.paragrafo is not distinct from v.p and l.texto=v.x;
